// src/hooks/UseExceptions.js
import { useCallback, useEffect, useState } from 'react';
import {
  fetchExceptionRules,
  createExceptionRule,
  deleteExceptionRule,
} from '../api/SettingsApi';

const STORAGE_KEY = 'watchservice.exceptions';

function saveLocal(list) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {}
}

function loadLocal() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function useExceptions() {
  const [exceptions, setExceptions] = useState(loadLocal());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const server = await fetchExceptionRules();
      const list = Array.isArray(server) ? server : [];
      setExceptions(list);
      saveLocal(list);
    } catch (e) {
      setError(e);
      const local = loadLocal();
      setExceptions(local);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  /**
   * payload: { type, pattern, memo }
   */
  const addException = useCallback(async (payload) => {
    const t = String(payload?.type || 'PATH').trim();
    const p = String(payload?.pattern || '').trim();
    const m = String(payload?.memo || '').trim();
    if (!p) return;

    setError(null);

    try {
      const created = await createExceptionRule({ type: t, pattern: p, memo: m });
      setExceptions((prev) => {
        const next = [created, ...(prev || [])].filter(Boolean);
        saveLocal(next);
        return next;
      });
    } catch (e) {
      // 서버 실패 시 로컬만 추가
      setError(e);
      const localId = Date.now();
      const fallback = { id: localId, type: t, pattern: p, memo: m };
      setExceptions((prev) => {
        const next = [fallback, ...(prev || [])];
        saveLocal(next);
        return next;
      });
    }
  }, []);

  const removeException = useCallback(async (id) => {
    if (id === undefined || id === null) return;

    setError(null);

    let prevSnapshot = null;
    setExceptions((prev) => {
      prevSnapshot = prev;
      const next = (prev || []).filter((x) => x.id !== id);
      saveLocal(next);
      return next;
    });

    try {
      await deleteExceptionRule(id);
    } catch (e) {
      setError(e);
      const rollback = prevSnapshot ?? loadLocal();
      setExceptions(rollback);
      saveLocal(rollback);
    }
  }, []);

  return {
    exceptions,
    loading,
    error,
    refresh,

    addException,
    removeException,

    setExceptions,
  };
}
